# -*- coding: utf-8 -*-
from common import md, esc, cq, wq, verse_card
def tbl(head, rows):
    return '<div class="tbl"><table><thead><tr>'+"".join(f'<th>{h}</th>' for h in head)+'</tr></thead><tbody>'+"".join('<tr>'+"".join(f'<td>{md(c)}</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def eras():
    E=[("🌳","创造","创1–2","神与人立约；人按神形像被造；安息","“太初有道”（约1:1）；“起初造人的”（太19:4）"),
       ("🍎","堕落","创3","第一亚当失败；女人后裔要伤蛇的头（创3:15）","旷野试探：末后的亚当得胜（路3:38–4:13）"),
       ("🌈","挪亚","创6–9","审判与拯救；保存世界","“挪亚的日子怎样，人子降临也要怎样”（太24:37）"),
       ("⭐","亚伯拉罕","创12–22","万国因你的后裔得福","“亚伯拉罕的后裔”（太1:1）；“亚伯拉罕欢欢喜喜地仰望我的日子”（约8:56）"),
       ("⛰️","摩西 / 出埃及","出1–24","逾越节、红海、吗哪、西奈之约、会幕","从埃及召出（太2:15）；山上颁律（太5–7）；生命的粮（约6）；逾越节羔羊（约1:29）"),
       ("👑","大卫","撒下7","永远的王位与国度","“大卫的子孙”（太1:1；可10:47）；骑驴进城（太21）"),
       ("⛓️","被掳与先知","赛40–66；耶31；结34–37；但7","新出埃及、新约、好牧人、人子","旷野的声音（可1:2-3）；人子（可14:62）；好牧人（约10）"),
       ("✝️","基督","四福音书","应许的应验：道成肉身、受死、复活","本站的焦点"),
       ("🔥","五旬节与教会","徒2","圣灵浇灌；使万民作门徒","大使命（太28:19）；保惠师（约14–16）；从耶路撒冷起（路24:47）"),
       ("🌅","再来与新创造","启21–22","身体复活、审判、新天新地","“人子要在他父的荣耀里……降临”（太16:27）；“万物复兴”（太19:28）")]
    s='<div class="eras">'
    for i,(ic,t,r,d,ep) in enumerate(E):
        s+=f'<div class="era reveal" style="--i:{i}"><span class="eic">{ic}</span><b>{t}</b><small>{r}</small><p>{d}</p><p class="epl">✝️ {esc(ep)}</p></div>'
    return s+'</div>'
def twoage():
    return '''<figure class="twoage glass reveal"><svg viewBox="0 0 1000 300" role="img" aria-label="天国已然未然图">
<defs><linearGradient id="ta1" x1="0" x2="1"><stop offset="0" stop-color="#7c8796"/><stop offset="1" stop-color="#e0573e"/></linearGradient><linearGradient id="ta2" x1="0" x2="1"><stop offset="0" stop-color="#f5b942"/><stop offset="1" stop-color="#3fd39a"/></linearGradient></defs>
<line x1="40" y1="200" x2="720" y2="200" stroke="url(#ta1)" stroke-width="10" stroke-linecap="round"/>
<path d="M420,200 Q420,90 520,90 L960,90" fill="none" stroke="url(#ta2)" stroke-width="10" stroke-linecap="round" class="draw"/>
<rect x="420" y="80" width="300" height="130" fill="#f5b942" opacity=".10" rx="14"/>
<circle cx="420" cy="200" r="13" fill="#f5b942"/><circle cx="720" cy="200" r="13" fill="#3fd39a"/>
<text x="60" y="240" font-size="22" fill="currentColor">今世：罪、撒但、死亡掌权</text>
<text x="600" y="60" font-size="22" fill="currentColor">来世：天国完全降临、新天新地</text>
<text x="420" y="270" font-size="20" text-anchor="middle" fill="#f5b942">基督降临 · 赶鬼 · 十字架 · 复活</text>
<text x="720" y="245" font-size="20" text-anchor="middle" fill="#3fd39a">人子再来</text>
<text x="570" y="160" font-size="22" text-anchor="middle" fill="currentColor" font-weight="700">天国 = 已然 / 未然</text>
</svg><figcaption>天国的两个阶段（参 Geerhardus Vos 的两世代图、Herman Ridderbos《神国的降临》1950，本站重绘）：天国已经随君王临到（芥菜种、面酵），却要等人子再来才完全显现（麦子与稗子到收割时才分开）。</figcaption></figure>'''
def covflow():
    C=[("创3:15","始约应许","女人的后裔要伤蛇的头","路10:18；约12:31"),("创9","挪亚之约","保存世界直到审判","太24:37-39"),("创12；15；17","亚伯拉罕之约","万国得福；“作你和你后裔的神”","太1:1；路1:55,73；约8:56"),
       ("出19–24","摩西之约","律法、献祭、立约之血","太5:17；可14:24"),("撒下7","大卫之约","永远的王","路1:32-33；太21:9"),("耶31:31-34","新约","心版、赦罪、认识神","路22:20；太26:28")]
    s='<div class="covflow">'
    for i,(r,t,d,ep) in enumerate(C):
        s+=f'<div class="cstep reveal" style="--i:{i}"><small>{r}</small><b>{t}</b><p>{d}</p><span class="cep">✝️ {ep}</span></div>'+('<i class="carr">➜</i>' if i<len(C)-1 else '')
    return s+'</div><p class="note">'+md("同一个==恩典之约==（应许的实质都是基督），在不同时代以不同方式施行；福音书记载的正是这约的**中保亲自来到**。")+'</p>'
def build():
    b=[]
    b.append('<h2 id="w1">一、先跳出框架：福音书在整本圣经中的位置</h2>')
    b.append('<h3 id="w1a">📚 正典中的四福音书</h3><div class="canon glass reveal"><div class="cz ot"><b>旧约 39 卷</b><span>律法 · 历史 · 诗歌 · 先知</span><em>应许 · 影儿 · 预言</em></div><div class="cz gos"><b>四福音书</b><span>马太 · 马可 · 路加 · 约翰</span><em>应验：基督亲自来到</em></div><div class="cz act"><b>使徒行传</b><span>复活的主藉圣灵继续工作</span><em>“耶稣开头一切所行所教训的”续篇</em></div><div class="cz ep"><b>书信 21 卷</b><span>保罗 13 · 希伯来书 · 大公 7</span><em>基督事件的意义与生活</em></div><div class="cz rev"><b>启示录</b><span>终局</span><em>完成</em></div></div>')
    b.append('<p>比利时信条第四条列明正典书卷，新约以四福音书开头：</p>'+cq(("bc",4,"新约圣经包括：四福音书，即马太福音、马可福音、路加福音及约翰福音；")))
    b.append(f'<div class="callout key-c"><b>💡 整体观：</b>{md("旧约是**应许**，福音书是**应验**，使徒行传与书信是**解释与扩展**，启示录是**完成**。福音书站在整本圣经的转折点上：它既是旧约故事的高潮（“日期满了”{{可1:15}}），也是新约教会的根基。四卷书不是四个不同的福音，而是**一个福音、四重见证**——早期教父爱任纽说福音是「四重形式、由一位圣灵维系的」。")}</div>')
    b.append('<p>海德堡要理问答第 19 问正好说出整本圣经的福音主线：</p>'+cq(("hc",19)))
    b.append('<h3 id="w1b">🧬 救赎历史主线：十个阶段在福音书中的回响</h3>'+eras())
    b.append('<h3 id="w1c">⏳ 天国：已然与未然</h3>'+twoage())
    b.append(f'<p>{md("耶稣的第一句公开宣讲是“日期满了，神的国近了。你们当悔改，信福音！”（{{可1:15}}）。“神的国”（马太多称“天国”）不是一块领土，而是**神的王权在历史中以救赎和审判的方式实现**。它在耶稣赶鬼时已经临到（{{太12:28}}），却要等到人子“在他荣耀里”降临时才完全（{{太25:31}}）。这就是福音书中“已经……还没有……”张力的来源。")}</p>')
    b.append('<h3 id="w1d">✝️ 四福音，一位基督</h3>'+tbl(["","马太","马可","路加","约翰"],[
        ["耶稣的画像","**君王**弥赛亚","受苦的**仆人**","**人子**、万人的救主","**神的儿子**、道成肉身"],
        ["原初读者","犹太基督徒","罗马外邦人","希腊人（提阿非罗）","小亚细亚教会与慕道者"],
        ["开头","亚伯拉罕、大卫的家谱","旷野的声音（直接进入事工）","史学序言与降生故事","“太初有道”（永恒）"],
        ["家谱","从亚伯拉罕往下","无（仆人不需家谱）","往上追到亚当","道在太初，无需人的家谱"],
        ["钥字","天国","立刻 / 仆人","救恩 / 今天","信 / 生命 / 我是"],
        ["钥节","{{太5:17}}","{{可10:45}}","{{路19:10}}","{{约20:31}}"],
        ["对应旧约“枝子”","“大卫的苗裔”（耶23:5）王","“我仆人大卫的苗裔”（亚3:8）","「名称为大卫苗裔的那人」（亚6:12）","“耶和华的苗裔”（赛4:2）"]]))
    b.append('<p class="note">“枝子/苗裔”对照是古老的读经传统（如十九世纪以来的福音派讲章），可作记忆辅助，但不是经文本身的意图声明。</p>')
    b.append('<h2 id="w2">二、圣经神学：福音书怎样读旧约</h2>')
    b.append('<h3 id="w2a">🔑 耶稣自己的读经法</h3>'+verse_card("路24:27")+verse_card("约5:39"))
    b.append(f'<p>{md("复活的主把**整本旧约**（摩西、先知、诗篇）当作指向自己的书来讲解。这是改革宗**以基督为中心**读经的根据：不是在每节经文里牵强地找基督，而是看每段经文在**救赎历史**中怎样走向基督。")}</p>')
    b.append(tbl(["旧约","福音书","神学意义"],[["创3:15 女人的后裔","{{路10:18}}；{{约12:31}}","撒但从天上坠落；这世界的王要被赶出去"],["创22 亚伯拉罕献以撒","{{约3:16}}；{{太3:17}}","“独生的”“爱子”：父不爱惜自己的儿子"],["出12 逾越节","{{约1:29}}；{{约19:36}}","神的羔羊，骨头一根也不折断"],["出16 吗哪","{{约6:32-35}}","从天上来的真粮"],["申18:15 像摩西的先知","{{太17:5}}；{{约6:14}}","“你们要听他”"],["撒下7 大卫之约","{{路1:32-33}}","坐他祖大卫的位，国也没有穷尽"],["诗110:1 坐在我右边","{{太22:41-46}}；{{可14:62}}","大卫称他为主"],["诗118:22 房角的头块石头","{{太21:42}}","被弃的成为房角石"],["赛53 受苦的仆人","{{可10:45}}；{{路22:37}}","赎价；“他被列在罪犯之中”"],["但7:13 人子驾云","{{可14:62}}；{{太28:18}}","天上地下所有的权柄"],["亚9:9 谦和的王","{{太21:5}}","骑驴进耶路撒冷"],["玛3:1；4:5 以利亚","{{太11:10-14}}","施洗约翰就是那要来的以利亚"]]))
    b.append('<h3 id="w2b">🪞 影儿与实体（预表论）</h3>')
    T=[("圣殿","我的身体（这殿）","约2:19-21"),("会幕（神住在人中间）","道成肉身“住在我们中间”","约1:14"),("铜蛇","人子必照样被举起来","约3:14"),("约拿三日三夜","人子在地里头三日三夜","太12:40"),("所罗门的智慧","“在这里有一人比所罗门更大”","太12:42"),("安息日","人子是安息日的主","可2:28"),("逾越节筵席","我的身体、我立约的血","路22:19-20"),("以色列在旷野四十年","耶稣在旷野四十天","太4:1-11")]
    b.append('<div class="types">'+"".join(f'<div class="type reveal"><span class="sh">{a}</span><i>➜</i><span class="re">{c}</span><small>{d}</small></div>' for a,c,d in T)+'</div>')
    b.append(cq(("bc",25)))
    b.append('<h3 id="w2c">🧭 救赎历史的读法（Vos · Ridderbos）</h3>')
    b.append(f'<div class="two"><div class="card glass"><h4>Geerhardus Vos（荷裔，普林斯顿）</h4><p>{md("“圣经神学”之父：启示是**有历史进程的**，随救赎行动逐步展开。他的《圣经神学》把耶稣的教训放在旧约启示的高峰：耶稣既是启示者，也是启示的内容。")}</p></div><div class="card glass"><h4>Herman Ridderbos（荷兰坎彭）</h4><p>{md("《神国的降临》（1950）：福音书的中心主题是**神国在耶稣身上的降临**，它是末世性的、却已在今世开始；耶稣的神迹、赦罪、比喻都是这国度临到的记号。这是欧陆改革宗对福音书研究的标志性贡献。")}</p></div></div>')
    b.append('<h2 id="w3">三、圣约神学：一个恩典之约，多次施行</h2>')
    b.append('<h3 id="w3a">🤝 圣约的历史脉络在福音书中的会合</h3>'+covflow())
    b.append('<h3 id="w3b">📙 威斯敏斯特的表述（长老会改革宗）</h3>'+wq('wcf',7,6))
    b.append('<h3 id="w3c">🇳🇱 欧陆改革宗的侧重</h3>')
    b.append(f'<p>{md("三项联合信条在洗礼、儿女与拣选的教导中充满圣约语言：信徒的儿女“与父母同属于神的圣约和教会”（HC 74）。荷兰传统（巴文克、Klaas Schilder 等，以及今日加拿大改革宗教会 canrc.org 所承接的传统）特别强调：**约包含应许与要求两面**。福音书中耶稣抱起小孩子、为他们祝福（{{可10:13-16}}），正显明神的约包括信徒的儿女。")}</p>')
    b.append(cq(("hc",74))+cq(("dort",1,17)))
    b.append('<h3 id="w3d">🧩 约的要素在福音书中</h3>'+tbl(["要素","内容","福音书经文"],[["立约的主动者","神（恩典的主权）","{{约6:37}}；{{约15:16}}"],["中保","耶稣基督：先知、祭司、君王","{{太17:5}}；{{约17:19}}；{{太28:18}}"],["应许","赦罪、永生、圣灵","{{太26:28}}；{{约10:28}}；{{路24:49}}"],["要求","悔改、信、跟从","{{可1:15}}；{{路9:23}}"],["记号与印证","洗礼与圣餐","{{太28:19}}；{{路22:19-20}}"],["祝福与咒诅","八福与祸哉","{{太5:3-12}}；{{太23:13-36}}"],["立约群体","新以色列：十二使徒、教会、儿女","{{太16:18}}；{{可10:14}}"]]))
    b.append('<h3 id="w3e">⚖️ 律法与福音</h3>')
    b.append(f'<p>{md("耶稣「不是要废掉律法，乃是要成全」（{{太5:17}}）。祂把律法总结为爱神与爱人（{{太22:37-40}}），又在登山宝训中揭开律法的属灵深度。改革宗：律法使人知罪而归向基督、约束罪恶、作感恩生活的准则。海德堡要理问答第 4 问引用的，正是耶稣在马太福音 22 章的总结。")}</p>')
    b.append(cq(("hc",4))+wq('wcf',19,6,"六、虽然真信徒不在行为之约的律法之下，不因此被称义或定罪。但律法无论是对他们还是其他人都有很大的用处。因为作为生活的准则，律法显明神的旨意和人的责任，约束人或指引人照着去做。"))
    b.append('<h2 id="w4">四、欧陆改革宗的读法</h2>')
    b.append('<h3 id="w4a">📖 唯独圣经与以经解经</h3>'+cq(("bc",7,"我们相信，圣经中包含了神全部的旨意；我们也相信它对人得救所必须信的一切真理作了充分的教导。"))+wq('wcf',1,9,"九、在解释《圣经》时，唯一无错谬的原则是「以经解经」。"))
    b.append('<h3 id="w4b">🔺 海德堡三段式在福音书中</h3>'+cq(("hc",2)))
    b.append('<div class="tri"><div class="tr t1 reveal"><b>① 罪与愁苦</b><span>HC 3–11</span><p>法利赛人与税吏（路18）</p><small>“从心里发出来的……这都是污秽人的”（可7:21-23）</small></div><div class="tr t2 reveal"><b>② 救赎</b><span>HC 12–85</span><p>十字架与空坟</p><small>“人子来……作多人的赎价”（可10:45）</small></div><div class="tr t3 reveal"><b>③ 感恩</b><span>HC 86–129</span><p>登山宝训、主祷文</p><small>“你们的光也当这样照在人前”（太5:16）</small></div></div>')
    b.append('<h2 id="w5">五、福音书的体裁与读法</h2>')
    b.append('<h3 id="w5a">📜 “福音”是什么体裁？</h3>'+f'<div class="card glass"><p>{md("福音书在形式上接近希腊罗马的**传记**（bios），但目的不同：它们是**宣讲**——宣告一位君王已经来到、成就了救恩。全书篇幅的三分之一到二分之一集中在最后一周，说明作者认为**十字架与复活是故事的高潮**。")}</p></div>')
    G=[("叙事","问：神在这段里做了什么？耶稣显明自己是谁？人物怎样回应？"),("比喻","找出一个中心要点；注意结尾的“翻转”；不要把每个细节都寓意化"),("神迹","是“神迹”（记号）：指向耶稣的身份与国度的临到，不只是展示能力"),("讲论","注意听众（门徒/群众/对手）与场合"),("对观平行","比较三卷的异同，看每位作者的强调"),("受难叙事","每卷都放慢节奏：注意时间、地点与旧约引用")]
    b.append('<div class="letter">'+"".join(f'<div class="lp reveal" style="--i:{i}"><b>{a}</b><span>{c}</span></div>' for i,(a,c) in enumerate(G))+'</div>')
    b.append('<h3 id="w5b">👁️ 八个视角读福音书</h3>')
    V=[("🏛️","历史","第二圣殿时期、罗马统治、地理"),("✍️","文学","结构、交错、重复、讽刺"),("📜","救赎历史","旧约应许怎样应验"),("🤝","圣约","立约之血、新以色列、儿女"),("📘","教义","基督的位格与工作、信条对照"),("⛪","教会","使徒、钥匙、圣礼、大使命"),("🌱","门徒","舍己、背十字架、彼此相爱"),("🌅","末世","天国已然未然、再来与审判")]
    b.append('<div class="views">'+"".join(f'<div class="view reveal"><span>{a}</span><b>{c}</b><p>{d}</p></div>' for a,c,d in V)+'</div>')
    return "".join(b)
